using Intropy.Topology.Building;
using Intropy.Topology.Model;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Entry point for declaring an integration system's topology. Add components, wire
/// them to topics and connectors, then call <see cref="Build"/> to materialize and
/// validate the immutable <see cref="SystemTopology"/>. Resources (topics, connectors)
/// materialize from usage — there is no <c>AddTopic</c>. Not thread-safe;
/// a second <see cref="Build"/> after further mutation reflects the mutations.
/// </summary>
public sealed class SystemBuilder
{
    private readonly List<Component> _components = [];

    /// <summary>The system's name (DNS-1123 label).</summary>
    public string SystemName { get; }

    private SystemBuilder(string systemName)
    {
        SystemName = systemName;
    }

    internal IReadOnlyList<Component> Components => _components;

    /// <summary>Creates a builder for a named system.</summary>
    /// <param name="systemName">The system's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static SystemBuilder Create(string systemName) =>
        new(NameRules.RequireLabel(systemName, nameof(systemName)));

    /// <summary>Adds an extractor: pulls data out of an external system and publishes it.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public ExtractorBuilder AddExtractor(string name) =>
        new(Register(new ExtractorComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a loader: consumes a topic and writes to an external system.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public LoaderBuilder AddLoader(string name) =>
        new(Register(new LoaderComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>Adds a transactional integration.</summary>
    /// <param name="name">The component's name (DNS-1123 label).</param>
    public TransactionalIntegrationBuilder AddTransactionalIntegration(string name) =>
        new(Register(new TransactionalIntegrationComponent(NameRules.RequireLabel(name, nameof(name)))));

    /// <summary>
    /// Materializes and validates the topology. Throws when any error-severity
    /// violation exists, carrying every diagnostic found.
    /// </summary>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public SystemTopology Build() =>
        TryBuild(out var topology, out var diagnostics)
            ? topology!
            : throw new TopologyValidationException(diagnostics);

    /// <summary>Non-throwing <see cref="Build"/>: returns false with the diagnostics when the topology is invalid.</summary>
    /// <param name="topology">The topology when valid; null otherwise.</param>
    /// <param name="diagnostics">All diagnostics found, including warnings.</param>
    public bool TryBuild(out SystemTopology? topology, out IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var candidate = TopologyMaterializer.Materialize(this);
        diagnostics = TopologyRules.Run(this, candidate);
        if (diagnostics.Any(d => d.Severity == DiagnosticSeverity.Error))
        {
            topology = null;
            return false;
        }

        topology = candidate;
        return true;
    }

    /// <summary>Runs validation without throwing; returns all diagnostics including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Validate() =>
        TopologyRules.Run(this, TopologyMaterializer.Materialize(this));

    private T Register<T>(T component) where T : Component
    {
        _components.Add(component);
        return component;
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// Represents a declared topology component and its recorded edges. Declaration methods
/// record intent; <see cref="SystemBuilder.Build"/> performs completeness and
/// cross-component validation. Instances are mutable during declaration and not thread-safe.
/// </summary>
public abstract class Component
{
    /// <summary>The output port name recorded for every <c>Publishes</c> call.</summary>
    internal const string DefaultPort = "default";

    private readonly List<TopicRef> _subscribes = [];
    private readonly List<(string Port, TopicRef Topic)> _publishes = [];
    private readonly List<(ConnectorRef Connector, ConnectorDirection Direction)> _connectors = [];
    private readonly List<ServiceRef> _services = [];

    private protected Component(string name, ComponentKind kind)
    {
        Name = name;
        Kind = kind;
    }

    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public string Name { get; }

    /// <summary>The component's block kind.</summary>
    public ComponentKind Kind { get; }

    internal IReadOnlyList<TopicRef> SubscribeCalls => _subscribes;

    internal IReadOnlyList<(string Port, TopicRef Topic)> PublishCalls => _publishes;

    internal IReadOnlyList<(ConnectorRef Connector, ConnectorDirection Direction)> ConnectorCalls => _connectors;

    internal IReadOnlyList<ServiceRef> ServiceCalls => _services;

    internal void AddSubscribe(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _subscribes.Add(topic);
    }

    internal void AddPublish(TopicRef topic)
    {
        ArgumentNullException.ThrowIfNull(topic);
        _publishes.Add((DefaultPort, topic));
    }

    internal void AddConnector(ConnectorRef connector, ConnectorDirection direction)
    {
        ArgumentNullException.ThrowIfNull(connector);
        _connectors.Add((connector, direction));
    }

    internal void AddService(ServiceRef service)
    {
        ArgumentNullException.ThrowIfNull(service);
        _services.Add(service);
    }
}

/// <summary>The declared extractor: an edge block that pulls or receives data from an
/// external system and publishes it. Obtained from the extractor builder's
/// <c>Component</c> property.</summary>
public sealed class ExtractorComponent : Component
{
    internal ExtractorComponent(string name) : base(name, ComponentKind.Extractor) { }
}

/// <summary>The declared loader: an edge block that consumes exactly one topic and writes
/// to an external system. Obtained from the loader builder's <c>Component</c> property.</summary>
public sealed class LoaderComponent : Component
{
    internal LoaderComponent(string name) : base(name, ComponentKind.Loader) { }
}

/// <summary>The declared transactional integration: a synchronous block that reads/writes
/// external systems through connectors. Obtained from the integration builder's
/// <c>Component</c> property.</summary>
public sealed class TransactionalIntegrationComponent : Component
{
    internal TransactionalIntegrationComponent(string name)
        : base(name, ComponentKind.TransactionalIntegration) { }
}

using System.Diagnostics.CodeAnalysis;
using Intropy.Topology.Validation;

namespace Intropy.Topology;

/// <summary>
/// Identifies a pub/sub topic by its Dapr component and topic names. The backing
/// resource materializes only when a component uses the reference.
/// </summary>
public abstract record TopicRef
{
    /// <summary>The Dapr pubsub component name (DNS-1123 subdomain).</summary>
    public string PubSubName { get; }

    /// <summary>The topic name within the pubsub (DNS-1123 subdomain).</summary>
    public string TopicName { get; }

    /// <summary>The event contract type carried on the topic.</summary>
    public abstract Type ContractType { get; }

    private protected TopicRef(string pubSubName, string topicName)
    {
        PubSubName = NameRules.RequireSubdomain(pubSubName, nameof(pubSubName));
        TopicName = NameRules.RequireSubdomain(topicName, nameof(topicName));
    }
}

/// <summary>
/// A <see cref="TopicRef"/> whose generic argument identifies the event contract. Topology
/// wiring uses the topic names, while <see cref="TopicRef.ContractType"/> exposes the type.
/// </summary>
/// <typeparam name="T">The event contract type published on the topic.</typeparam>
public sealed record TopicRef<T> : TopicRef
{
    /// <inheritdoc />
    public override Type ContractType => typeof(T);

    private TopicRef(string pubSubName, string topicName)
        : base(pubSubName, topicName)
    {
    }

    /// <summary>Declares a topic on a pubsub component.</summary>
    /// <param name="pubSubName">The Dapr pubsub component name (DNS-1123 subdomain).</param>
    /// <param name="topicName">The topic name (DNS-1123 subdomain).</param>
    /// <exception cref="ArgumentException">A name is not a valid DNS-1123 subdomain.</exception>
    public static TopicRef<T> Define(
        [ConstantExpected] string pubSubName,
        [ConstantExpected] string topicName) =>
        new(pubSubName, topicName);
}

/// <summary>
/// Identifies a platform service by the Dapr app ID callers use. The app ID is a minted
/// identity: deployment honors it rather than maintaining its own copy. It is unqualified —
/// Dapr service resolution in a cluster is namespace-scoped, so the identity holds within
/// the system's own namespace. The service materializes from component usage; this reference
/// neither owns nor deploys its provider.
/// </summary>
public sealed record ServiceRef
{
    /// <summary>The service's Dapr app ID (DNS-1123 label).</summary>
    public string AppId { get; }

    private ServiceRef(string appId) => AppId = NameRules.RequireLabel(appId, nameof(appId));

    /// <summary>Declares a reusable external platform-service identity.</summary>
    /// <param name="appId">The Dapr app ID callers invoke.</param>
    /// <exception cref="ArgumentException">The app ID is not a valid DNS-1123 label.</exception>
    public static ServiceRef Define([ConstantExpected] string appId) => new(appId);
}

/// <summary>
/// A connector — the named connection point between the system and the outside world.
/// Every edge block reaches the outside world through a connector. The name is the whole
/// identity: the Dapr binding component's name is always derived
/// (<c>binding.&lt;connector-name&gt;</c>), never declared, and the binding's deployed
/// <c>spec.type</c> (with its address and credentials) is environment-owned deployment
/// configuration the topology deliberately does not repeat. Local F5 runs substitute their
/// own resolution via the development definition. Connectors are declared in the SystemHost
/// (typically a scaffolded <c>Connectors.cs</c>); they are system-owned and never shared
/// across systems. Direction is not part of the identity — it follows from usage
/// (<c>From</c> / <c>To</c>).
/// </summary>
public sealed record ConnectorRef
{
    /// <summary>The connector's name (DNS-1123 label, e.g. <c>pim</c>).</summary>
    public string Name { get; }

    private ConnectorRef(string name) => Name = name;

    /// <summary>Declares a connector.</summary>
    /// <param name="name">The connector's name (DNS-1123 label).</param>
    /// <exception cref="ArgumentException">The name is not a valid DNS-1123 label.</exception>
    public static ConnectorRef Define([ConstantExpected] string name) =>
        new(NameRules.RequireLabel(name, nameof(name)));
}

using System.Reflection;
using Intropy.Topology.Model;

namespace Intropy.Topology;

/// <summary>
/// A discoverable system declaration. A system is a type implementing this interface; it names the
/// system and declares its topology into the supplied <see cref="SystemBuilder"/>.
/// <see cref="SystemDiscovery.Discover"/> finds, instantiates, and builds it.
/// </summary>
public interface ISystemDefinition
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    string SystemName { get; }

    /// <summary>Declares the system's components and edges into <paramref name="builder"/>.</summary>
    /// <param name="builder">A builder created for <see cref="SystemName"/>.</param>
    void Define(SystemBuilder builder);
}

/// <summary>The result of discovering a system: its validated topology and the definition instance.</summary>
/// <param name="Topology">The materialized, validated topology.</param>
/// <param name="Definition">The definition instance (carries optional seams such as dev profiles).</param>
public sealed record DiscoveredSystem(SystemTopology Topology, ISystemDefinition Definition);

/// <summary>Discovers and builds the single <see cref="ISystemDefinition"/> declared in an assembly.</summary>
public static class SystemDiscovery
{
    /// <summary>
    /// Finds the one concrete <see cref="ISystemDefinition"/> in <paramref name="assembly"/>,
    /// instantiates it via its parameterless constructor, declares its topology, and validates it.
    /// </summary>
    /// <param name="assembly">The assembly to scan.</param>
    /// <returns>The validated topology and the definition instance.</returns>
    /// <exception cref="InvalidOperationException">No definition, or more than one, was found.</exception>
    /// <exception cref="TopologyValidationException">The declared topology is invalid.</exception>
    public static DiscoveredSystem Discover(Assembly assembly)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        return DiscoverFrom(assembly.GetName().Name ?? assembly.ToString(), assembly.GetTypes());
    }

    internal static DiscoveredSystem DiscoverFrom(string source, IReadOnlyList<Type> types)
    {
        var (definition, builder) = Declare(source, types);
        return new DiscoveredSystem(builder.Build(), definition);
    }

    /// <summary>
    /// Discovery for read-only inspection (the <c>graph</c> verb): like <see cref="Discover"/>,
    /// but warning-severity diagnostics do not fail — the materialized topology is returned
    /// alongside them so a partially built system can still be inspected. Error-severity
    /// violations still throw.
    /// </summary>
    /// <param name="assembly">The assembly to scan.</param>
    /// <param name="diagnostics">All diagnostics found, including the tolerated warnings.</param>
    /// <returns>The materialized topology and the definition instance.</returns>
    /// <exception cref="InvalidOperationException">No definition, or more than one, was found.</exception>
    /// <exception cref="TopologyValidationException">The declared topology has error-severity violations.</exception>
    public static DiscoveredSystem DiscoverTolerant(Assembly assembly, out IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        var (definition, builder) = Declare(assembly.GetName().Name ?? assembly.ToString(), assembly.GetTypes());
        if (!builder.TryBuild(out var topology, out diagnostics))
        {
            throw new TopologyValidationException(diagnostics);
        }

        return new DiscoveredSystem(topology!, definition);
    }

    private static (ISystemDefinition Definition, SystemBuilder Builder) Declare(string source, IReadOnlyList<Type> types)
    {
        var definition = FindSingleDefinition(source, types);
        var builder = SystemBuilder.Create(definition.SystemName);
        definition.Define(builder);
        return (definition, builder);
    }

    private static ISystemDefinition FindSingleDefinition(string source, IReadOnlyList<Type> types)
    {
        var candidates = types
            .Where(t => t is { IsAbstract: false, IsInterface: false } && typeof(ISystemDefinition).IsAssignableFrom(t))
            .ToList();

        if (candidates.Count == 0)
        {
            throw new InvalidOperationException(
                $"No {nameof(ISystemDefinition)} was found in '{source}'.");
        }

        if (candidates.Count > 1)
        {
            throw new InvalidOperationException(
                $"Multiple {nameof(ISystemDefinition)} types were found in '{source}': " +
                $"{string.Join(", ", candidates.Select(t => t.FullName))}. Exactly one is required.");
        }

        return (ISystemDefinition)Activator.CreateInstance(candidates[0])!;
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Building;

/// <summary>
/// Base class for builders that declare a topology component and its permitted edges.
/// Each derived builder exposes only the operations valid for its component kind, so
/// invalid edges cannot be declared. Fluent methods return the derived builder type,
/// and <see cref="Component"/> provides the typed component declared by the builder.
/// Not thread-safe.
/// </summary>
/// <typeparam name="TSelf">The concrete component builder type.</typeparam>
/// <typeparam name="TComponent">The typed component the builder declares.</typeparam>
public abstract class ComponentBuilder<TSelf, TComponent>
    where TSelf : ComponentBuilder<TSelf, TComponent>
    where TComponent : Component
{
    private protected ComponentBuilder(TComponent component) => Component = component;

    /// <summary>The typed component this builder declares — hold it to reference the block later.</summary>
    public TComponent Component { get; }
}

/// <summary>Fluent builder for an extractor: an edge block that pulls or receives data
/// from an external system and publishes it to at least one topic.</summary>
public sealed class ExtractorBuilder : ComponentBuilder<ExtractorBuilder, ExtractorComponent>
{
    internal ExtractorBuilder(ExtractorComponent component) : base(component) { }

    /// <summary>Declares that the extractor reads from the outside world through a connector.</summary>
    /// <param name="connector">The connector to read from.</param>
    public ExtractorBuilder From(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.In);
        return this;
    }

    /// <summary>Declares that the extractor publishes to a topic.</summary>
    /// <param name="topic">The topic to publish to.</param>
    public ExtractorBuilder Publishes(TopicRef topic)
    {
        Component.AddPublish(topic);
        return this;
    }

    /// <summary>Declares that the extractor invokes an external platform service.</summary>
    /// <param name="service">The Dapr app identity invoked by the extractor.</param>
    public ExtractorBuilder Uses(ServiceRef service)
    {
        Component.AddService(service);
        return this;
    }
}

/// <summary>Fluent builder for a loader: an edge block that subscribes to exactly one topic
/// and writes to an external system through a connector; loaders publish nothing.</summary>
public sealed class LoaderBuilder : ComponentBuilder<LoaderBuilder, LoaderComponent>
{
    internal LoaderBuilder(LoaderComponent component) : base(component) { }

    /// <summary>Declares the single topic the loader subscribes to.</summary>
    /// <param name="topic">The topic whose events the loader consumes.</param>
    public LoaderBuilder Subscribes(TopicRef topic)
    {
        Component.AddSubscribe(topic);
        return this;
    }

    /// <summary>Declares that the loader writes to the outside world through a connector.</summary>
    /// <param name="connector">The connector to write to.</param>
    public LoaderBuilder To(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.Out);
        return this;
    }

    /// <summary>Declares that the loader invokes an external platform service.</summary>
    /// <param name="service">The Dapr app identity invoked by the loader.</param>
    public LoaderBuilder Uses(ServiceRef service)
    {
        Component.AddService(service);
        return this;
    }
}

/// <summary>Fluent builder for a transactional integration: a synchronous block that
/// reads/writes external systems through connectors; it publishes no topics.</summary>
public sealed class TransactionalIntegrationBuilder
    : ComponentBuilder<TransactionalIntegrationBuilder, TransactionalIntegrationComponent>
{
    internal TransactionalIntegrationBuilder(TransactionalIntegrationComponent component)
        : base(component) { }

    /// <summary>Declares that the integration reads from an external system through a connector.</summary>
    /// <param name="connector">The connector to read from.</param>
    public TransactionalIntegrationBuilder From(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.In);
        return this;
    }

    /// <summary>Declares that the integration writes to an external system through a connector.</summary>
    /// <param name="connector">The connector to write to.</param>
    public TransactionalIntegrationBuilder To(ConnectorRef connector)
    {
        Component.AddConnector(connector, ConnectorDirection.Out);
        return this;
    }

    /// <summary>Declares that the integration invokes an external platform service.</summary>
    /// <param name="service">The Dapr app identity invoked by the integration.</param>
    public TransactionalIntegrationBuilder Uses(ServiceRef service)
    {
        Component.AddService(service);
        return this;
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Building;

/// <summary>
/// Folds the builder declarations into the immutable model: components in declaration
/// order, resources deduplicated from usage and sorted for determinism. Materialization
/// never fails — structurally broken declarations still materialize (first-seen wins on
/// conflicts) so validation rules can inspect and report the full picture.
/// </summary>
internal static class TopologyMaterializer
{
    public static SystemTopology Materialize(SystemBuilder builder)
    {
        var components = new List<ComponentModel>();
        var topics = new Dictionary<(string PubSub, string Topic), TopicAccumulator>();
        var connectors = new Dictionary<string, ConnectorAccumulator>();
        var services = new Dictionary<string, ServiceAccumulator>(StringComparer.Ordinal);

        foreach (var component in builder.Components)
        {
            components.Add(MaterializeComponent(component, topics, connectors, services));
        }

        return new SystemTopology
        {
            SystemName = builder.SystemName,
            Components = components,
            Topics = topics
                .OrderBy(t => t.Key.PubSub, StringComparer.Ordinal)
                .ThenBy(t => t.Key.Topic, StringComparer.Ordinal)
                .Select(t => new TopicResource
                {
                    PubSubName = t.Key.PubSub,
                    TopicName = t.Key.Topic,
                    ContractTypeName = t.Value.ContractTypeName,
                    Publishers = [.. t.Value.Publishers],
                    Subscribers = [.. t.Value.Subscribers],
                })
                .ToArray(),
            Connectors = connectors
                .OrderBy(c => c.Key, StringComparer.Ordinal)
                .Select(c => new ConnectorResource
                {
                    Name = c.Key,
                    Directions = [.. c.Value.Directions.Order()],
                    UsedBy = [.. c.Value.UsedBy],
                })
                .ToArray(),
            Services = services
                .OrderBy(s => s.Key, StringComparer.Ordinal)
                .Select(s => new ServiceResource { AppId = s.Key, Consumers = [.. s.Value.Consumers] })
                .ToArray(),
        };
    }

    private static ComponentModel MaterializeComponent(
        Component component,
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        Dictionary<string, ConnectorAccumulator> connectors,
        Dictionary<string, ServiceAccumulator> services)
    {
        var subscribes = new List<TopicSubscription>();
        foreach (var topic in component.SubscribeCalls)
        {
            subscribes.Add(new TopicSubscription
            {
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Subscribers.Add(component.Name);
        }

        var publishes = new List<PublishEdge>();
        foreach (var (port, topic) in component.PublishCalls)
        {
            publishes.Add(new PublishEdge
            {
                Port = port,
                PubSubName = topic.PubSubName,
                TopicName = topic.TopicName,
            });
            AccumulateTopic(topics, topic).Publishers.Add(component.Name);
        }

        var connectorEdges = new List<ConnectorEdge>();
        var seenConnectorEdges = new HashSet<(string, ConnectorDirection)>();
        foreach (var (connector, direction) in component.ConnectorCalls)
        {
            AccumulateConnector(connectors, connector, direction).UsedBy.Add(component.Name);
            if (seenConnectorEdges.Add((connector.Name, direction)))
            {
                connectorEdges.Add(new ConnectorEdge { ConnectorName = connector.Name, Direction = direction });
            }
        }

        var serviceAppIds = new List<string>();
        var seenServices = new HashSet<string>(StringComparer.Ordinal);
        foreach (var service in component.ServiceCalls)
        {
            if (!services.TryGetValue(service.AppId, out var accumulator))
            {
                services[service.AppId] = accumulator = new ServiceAccumulator();
            }

            accumulator.Consumers.Add(component.Name);
            if (seenServices.Add(service.AppId))
            {
                serviceAppIds.Add(service.AppId);
            }
        }

        return new ComponentModel
        {
            Name = component.Name,
            Kind = component.Kind,
            Subscribes = subscribes,
            Publishes = publishes,
            Connectors = connectorEdges,
            Uses = serviceAppIds,
        };
    }

    private static TopicAccumulator AccumulateTopic(
        Dictionary<(string PubSub, string Topic), TopicAccumulator> topics,
        TopicRef topic)
    {
        var key = (topic.PubSubName, topic.TopicName);
        if (!topics.TryGetValue(key, out var accumulator))
        {
            accumulator = new TopicAccumulator(topic.ContractType.FullName ?? topic.ContractType.Name);
            topics[key] = accumulator;
        }

        return accumulator;
    }

    private static ConnectorAccumulator AccumulateConnector(
        Dictionary<string, ConnectorAccumulator> connectors,
        ConnectorRef connector,
        ConnectorDirection direction)
    {
        if (!connectors.TryGetValue(connector.Name, out var accumulator))
        {
            accumulator = new ConnectorAccumulator();
            connectors[connector.Name] = accumulator;
        }

        accumulator.Directions.Add(direction);
        return accumulator;
    }

    private sealed class TopicAccumulator(string contractTypeName)
    {
        public string ContractTypeName { get; } = contractTypeName;
        public SortedSet<string> Publishers { get; } = new(StringComparer.Ordinal);
        public SortedSet<string> Subscribers { get; } = new(StringComparer.Ordinal);
    }

    private sealed class ServiceAccumulator
    {
        public SortedSet<string> Consumers { get; } = new(StringComparer.Ordinal);
    }

    private sealed class ConnectorAccumulator
    {
        public HashSet<ConnectorDirection> Directions { get; } = [];
        public SortedSet<string> UsedBy { get; } = new(StringComparer.Ordinal);
    }
}

namespace Intropy.Topology.Model;

/// <summary>
/// One component in the system: an integration block or a container service, together
/// with all of its edges. Everything about the workload shape (hosting model, activation,
/// ports, process lifetime) lives in the component's own scaffold, not in the topology.
/// </summary>
public sealed record ComponentModel
{
    /// <summary>The component's name (K8s resource name / Dapr app-id).</summary>
    public required string Name { get; init; }

    /// <summary>The component kind this component was declared as.</summary>
    public required ComponentKind Kind { get; init; }

    /// <summary>Topics the component subscribes to.</summary>
    public required IReadOnlyList<TopicSubscription> Subscribes { get; init; }

    /// <summary>Topics the component publishes to, by output port.</summary>
    public required IReadOnlyList<PublishEdge> Publishes { get; init; }

    /// <summary>Connectors the component uses (explicit From/To usage).</summary>
    public required IReadOnlyList<ConnectorEdge> Connectors { get; init; }

    /// <summary>External platform-service app IDs the component invokes.</summary>
    public required IReadOnlyList<string> Uses { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>A topic a component subscribes to.</summary>
public sealed record TopicSubscription
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

/// <summary>A component publishing to a topic through a named output port.</summary>
public sealed record PublishEdge
{
    /// <summary>The output port name (<c>default</c> when no port was given).</summary>
    public required string Port { get; init; }

    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }
}

/// <summary>A component using a connector in one direction.</summary>
public sealed record ConnectorEdge
{
    /// <summary>The connector's name.</summary>
    public required string ConnectorName { get; init; }

    /// <summary>The direction the connector is used in.</summary>
    public required ConnectorDirection Direction { get; init; }
}

using System.Text.Json.Serialization;

namespace Intropy.Topology.Model;

/// <summary>
/// A topic materialized from usage, with its publishing and subscribing component names
/// precomputed in ordinal sort order.
/// </summary>
public sealed record TopicResource
{
    /// <summary>The Dapr pubsub component name.</summary>
    public required string PubSubName { get; init; }

    /// <summary>The topic name.</summary>
    public required string TopicName { get; init; }

    /// <summary>Full name of the event contract type carried on the topic.</summary>
    public required string ContractTypeName { get; init; }

    /// <summary>Names of components publishing to the topic (sorted).</summary>
    public required IReadOnlyList<string> Publishers { get; init; }

    /// <summary>Names of components subscribed to the topic (sorted).</summary>
    public required IReadOnlyList<string> Subscribers { get; init; }
}

/// <summary>An external platform service materialized from component usage.</summary>
public sealed record ServiceResource
{
    /// <summary>The Dapr app ID callers invoke.</summary>
    public required string AppId { get; init; }

    /// <summary>Names of components invoking this service, sorted ordinally.</summary>
    public required IReadOnlyList<string> Consumers { get; init; }
}

/// <summary>A system-owned connector materialized from usage.</summary>
public sealed record ConnectorResource
{
    /// <summary>The connector's name (DNS-1123 label) — its whole identity.</summary>
    public required string Name { get; init; }

    /// <summary>The derived Dapr binding component name: <c>binding.&lt;connector-name&gt;</c>.</summary>
    public string DaprComponentName => $"binding.{Name}";

    /// <summary>The union of directions the connector is used in.</summary>
    public required IReadOnlyList<ConnectorDirection> Directions { get; init; }

    /// <summary>Names of components using the connector (sorted).</summary>
    public required IReadOnlyList<string> UsedBy { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>
/// The immutable, validated topology of one integration system: its components (in
/// declaration order) and the resources materialized from their usage (sorted).
/// Plain serializable data — generation tooling consumes this model.
/// </summary>
public sealed record SystemTopology
{
    /// <summary>The system's name (DNS-1123 label).</summary>
    public required string SystemName { get; init; }

    /// <summary>All components, in declaration order.</summary>
    public required IReadOnlyList<ComponentModel> Components { get; init; }

    /// <summary>Topics materialized from publish and subscribe edges.</summary>
    public required IReadOnlyList<TopicResource> Topics { get; init; }

    /// <summary>Connectors materialized from connector usage.</summary>
    public required IReadOnlyList<ConnectorResource> Connectors { get; init; }

    /// <summary>External platform services materialized from component usage.</summary>
    public required IReadOnlyList<ServiceResource> Services { get; init; }
}

namespace Intropy.Topology.Model;

/// <summary>The kind a component was declared as.</summary>
public enum ComponentKind
{
    /// <summary>Pulls data out of an external system and publishes it.</summary>
    Extractor,

    /// <summary>Consumes a topic and writes to an external system.</summary>
    Loader,

    /// <summary>End-to-end transactional integration.</summary>
    TransactionalIntegration,
}

/// <summary>The direction a component uses a connector in.</summary>
public enum ConnectorDirection
{
    /// <summary>Reads from the external system (<c>From</c> / connector trigger).</summary>
    In,

    /// <summary>Writes to the external system (<c>To</c>).</summary>
    Out,
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>Services cannot repeat per component or collide with component app IDs.</summary>
internal sealed class ServiceUsageRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            foreach (var duplicate in component.ServiceCalls
                .GroupBy(service => service.AppId, StringComparer.Ordinal)
                .Where(group => group.Count() > 1))
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"Component '{component.Name}' uses service '{duplicate.Key}' more than once.",
                    component.Name);
            }
        }

        var componentNames = context.Topology.Components
            .Select(component => component.Name)
            .ToHashSet(StringComparer.Ordinal);
        foreach (var service in context.Topology.Services.Where(service => componentNames.Contains(service.AppId)))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"Service app ID '{service.AppId}' collides with a topology component app ID.",
                service.AppId);
        }
    }
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>
/// A component must not publish more than one topic. Every <c>Publishes</c> call
/// records the single <c>default</c> output port; multi-output components (named ports)
/// are not part of the minimal model.
/// </summary>
internal sealed class DuplicatePortRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            if (component.PublishCalls.Count > 1)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The component declares {component.PublishCalls.Count} Publishes calls; a component publishes exactly one topic.",
                    component.Name);
            }
        }
    }
}

/// <summary>A component must not subscribe to the same topic more than once.</summary>
internal sealed class DuplicateSubscriptionRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            var duplicates = component.SubscribeCalls
                .GroupBy(t => (t.PubSubName, t.TopicName))
                .Where(g => g.Count() > 1);

            foreach (var group in duplicates)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Error,
                    $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is subscribed to more than once by the same component.",
                    component.Name);
            }
        }
    }
}

/// <summary>One topic must not be used with two different event contract types.</summary>
internal sealed class TopicContractConflictRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var usages = context.Builder.Components.SelectMany(TopicUsages);

        var conflicts = usages
            .GroupBy(t => (t.PubSubName, t.TopicName))
            .Where(g => g.Select(t => t.ContractType).Distinct().Count() > 1);

        foreach (var group in conflicts)
        {
            var contracts = string.Join(
                ", ",
                group.Select(t => t.ContractType.FullName ?? t.ContractType.Name).Distinct().Order(StringComparer.Ordinal));
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The topic '{group.Key.TopicName}' on pubsub '{group.Key.PubSubName}' is declared with conflicting contract types: {contracts}.",
                group.Key.TopicName);
        }
    }

    private static IEnumerable<TopicRef> TopicUsages(Component component)
    {
        foreach (var (_, topic) in component.PublishCalls)
        {
            yield return topic;
        }

        foreach (var topic in component.SubscribeCalls)
        {
            yield return topic;
        }
    }
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>Every component needs a unique name.</summary>
internal sealed class DuplicateComponentNameRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var duplicates = context.Topology.Components
            .GroupBy(c => c.Name, StringComparer.Ordinal)
            .Where(g => g.Count() > 1);

        foreach (var group in duplicates)
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The component name '{group.Key}' is declared {group.Count()} times; component names must be unique.",
                group.Key);
        }
    }
}

/// <summary>A system must declare at least one component.</summary>
internal sealed class EmptySystemRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        if (context.Topology.Components.Count == 0)
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                "The system declares no components.",
                context.Topology.SystemName);
        }
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation.Rules;

/// <summary>
/// Block kinds with a required output must declare it — extractors must publish.
/// The block builders prevent illegal calls but cannot force missing ones. A loader's
/// destination may stay a private local component, so a loader without a <c>To</c> call
/// is legal.
/// </summary>
internal sealed class MissingRequiredOutputRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            var missing = component.Kind switch
            {
                ComponentKind.Extractor when component.PublishCalls.Count == 0 =>
                    "Extractor components must publish to at least one topic; add a Publishes call.",
                _ => null,
            };

            if (missing is not null)
            {
                yield return new TopologyDiagnostic(DiagnosticSeverity.Error, missing, component.Name);
            }
        }
    }
}

/// <summary>
/// Block kinds that consume topics must subscribe correctly — loaders to exactly
/// one topic. The block builders prevent illegal calls but cannot force a required
/// subscription.
/// </summary>
internal sealed class MissingRequiredSubscriptionRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Builder.Components)
        {
            var count = component.SubscribeCalls.Count;
            var message = component.Kind switch
            {
                ComponentKind.Loader when count != 1 =>
                    "Loader components must subscribe to exactly one topic.",
                _ => null,
            };

            if (message is not null)
            {
                yield return new TopologyDiagnostic(DiagnosticSeverity.Error, message, component.Name);
            }
        }
    }
}

/// <summary>
/// Every published topic should have a subscriber. A message published into the
/// system with no consumer is a broken contract, not a fan-out reserve — but the
/// consumer may simply not exist yet, so the rule warns and local runs proceed.
/// Deployment validation is where an unconsumed topic becomes an error.
/// </summary>
internal sealed class UnconsumedTopicRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var topic in context.Topology.Topics.Where(t => t.Subscribers.Count == 0))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Warning,
                $"The topic '{topic.TopicName}' on pubsub '{topic.PubSubName}' is published but no component subscribes to it.",
                topic.TopicName);
        }
    }
}

/// <summary>
/// Every subscribed topic should have a publisher. A subscription nothing publishes
/// to will never receive a message — but the publisher may simply not exist yet,
/// so the rule warns and local runs proceed. Deployment validation is where an
/// unproduced topic becomes an error.
/// </summary>
internal sealed class UnproducedTopicRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var topic in context.Topology.Topics.Where(t => t.Publishers.Count == 0))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Warning,
                $"The topic '{topic.TopicName}' on pubsub '{topic.PubSubName}' is subscribed to but no component publishes it.",
                topic.TopicName);
        }
    }
}

namespace Intropy.Topology.Validation.Rules;

/// <summary>Warning: a component with no edges at all is likely unfinished.</summary>
internal sealed class NoEdgesRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        foreach (var component in context.Topology.Components)
        {
            var hasEdges =
                component.Subscribes.Count > 0
                || component.Publishes.Count > 0
                || component.Connectors.Count > 0;

            if (!hasEdges)
            {
                yield return new TopologyDiagnostic(
                    DiagnosticSeverity.Warning,
                    "The component has no edges (no subscriptions, publishes, or connectors); it is likely unfinished.",
                    component.Name);
            }
        }
    }
}

/// <summary>
/// A pubsub name must not equal a connector's derived Dapr binding component name
/// (<c>binding.&lt;connector-name&gt;</c>) — both become Dapr Component names in the same
/// Kubernetes namespace.
/// </summary>
internal sealed class PubSubConnectorNameCollisionRule : ITopologyRule
{
    public IEnumerable<TopologyDiagnostic> Evaluate(ValidationContext context)
    {
        var pubSubNames = context.Topology.Topics
            .Select(t => t.PubSubName)
            .ToHashSet(StringComparer.Ordinal);

        foreach (var connector in context.Topology.Connectors
            .Where(c => pubSubNames.Contains(c.DaprComponentName)))
        {
            yield return new TopologyDiagnostic(
                DiagnosticSeverity.Error,
                $"The pubsub name '{connector.DaprComponentName}' equals the Dapr binding component name derived from connector '{connector.Name}'; both become Dapr Component names in the same namespace.",
                connector.DaprComponentName);
        }
    }
}

using Intropy.Topology.Model;

namespace Intropy.Topology.Validation;

/// <summary>Runs every topology rule and collects the diagnostics.</summary>
internal static class TopologyRules
{
    private static readonly ITopologyRule[] Rules =
    [
        new Rules.DuplicateComponentNameRule(),
        new Rules.EmptySystemRule(),
        new Rules.DuplicatePortRule(),
        new Rules.DuplicateSubscriptionRule(),
        new Rules.TopicContractConflictRule(),
        new Rules.MissingRequiredOutputRule(),
        new Rules.MissingRequiredSubscriptionRule(),
        new Rules.UnconsumedTopicRule(),
        new Rules.UnproducedTopicRule(),
        new Rules.NoEdgesRule(),
        new Rules.PubSubConnectorNameCollisionRule(),
        new Rules.ServiceUsageRule(),
    ];

    public static IReadOnlyList<TopologyDiagnostic> Run(SystemBuilder builder, SystemTopology topology)
    {
        var context = new ValidationContext(builder, topology);
        return Rules.SelectMany(rule => rule.Evaluate(context)).ToArray();
    }
}

namespace Intropy.Topology.Validation;

/// <summary>
/// Name syntax rules for topology identifiers. Short names (system, component, port,
/// endpoint, connector) must be DNS-1123 labels because they become Kubernetes resource
/// names, Dapr app-ids, or derived Dapr binding component names
/// (<c>binding.&lt;connector-name&gt;</c>); resource names (topic, pubsub, service) must be
/// DNS-1123 subdomains because they become Dapr Component <c>metadata.name</c> values.
/// </summary>
internal static class NameRules
{
    private const int MaxLabelLength = 63;
    private const int MaxSubdomainLength = 253;

    public static bool IsValidLabel(string value) =>
        value.Length is > 0 and <= MaxLabelLength && IsLabelChunk(value);

    public static bool IsValidSubdomain(string value)
    {
        if (value.Length is 0 or > MaxSubdomainLength)
        {
            return false;
        }

        foreach (var part in value.Split('.'))
        {
            if (part.Length is 0 or > MaxLabelLength || !IsLabelChunk(part))
            {
                return false;
            }
        }

        return true;
    }

    public static string RequireLabel(string value, string paramName)
    {
        ArgumentNullException.ThrowIfNull(value, paramName);
        if (!IsValidLabel(value))
        {
            throw new ArgumentException(
                $"'{value}' is not a valid name: must be a DNS-1123 label " +
                $"(lowercase alphanumerics and '-', starting and ending with an alphanumeric, at most {MaxLabelLength} characters).",
                paramName);
        }

        return value;
    }

    public static string RequireSubdomain(string value, string paramName)
    {
        ArgumentNullException.ThrowIfNull(value, paramName);
        if (!IsValidSubdomain(value))
        {
            throw new ArgumentException(
                $"'{value}' is not a valid name: must be a DNS-1123 subdomain " +
                $"(lowercase alphanumeric labels separated by '.', each label at most {MaxLabelLength} characters, " +
                $"at most {MaxSubdomainLength} characters in total).",
                paramName);
        }

        return value;
    }

    private static bool IsLabelChunk(string value)
    {
        if (!char.IsAsciiLetterLower(value[0]) && !char.IsAsciiDigit(value[0]))
        {
            return false;
        }

        if (!char.IsAsciiLetterLower(value[^1]) && !char.IsAsciiDigit(value[^1]))
        {
            return false;
        }

        foreach (var c in value)
        {
            if (!char.IsAsciiLetterLower(c) && !char.IsAsciiDigit(c) && c != '-')
            {
                return false;
            }
        }

        return true;
    }
}

