using System.Text;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>A single generated artifact: a relative path and its text content.</summary>
/// <param name="RelativePath">Path relative to the output root (forward slashes).</param>
/// <param name="Content">The file's text content.</param>
public sealed record GeneratedFile(string RelativePath, string Content);

/// <summary>The artifacts generated for a system: Dapr component YAML and per-component runtime config.</summary>
public sealed class GeneratedArtifacts
{
    /// <summary>Subdirectory holding Dapr component YAML — the value for a sidecar's resources-path.</summary>
    public const string ComponentsDir = "components";

    /// <summary>Subdirectory holding per-component runtime config.</summary>
    public const string ConfigDir = "config";

    internal GeneratedArtifacts(IReadOnlyList<GeneratedFile> files) => Files = files;

    /// <summary>All generated files, in deterministic order.</summary>
    public IReadOnlyList<GeneratedFile> Files { get; }

    /// <summary>Writes every artifact under <paramref name="directory"/>, creating subdirectories.</summary>
    /// <param name="directory">The output root.</param>
    public void WriteTo(string directory)
    {
        ArgumentException.ThrowIfNullOrEmpty(directory);
        foreach (var file in Files)
        {
            var path = Path.Combine(directory, file.RelativePath.Replace('/', Path.DirectorySeparatorChar));
            Directory.CreateDirectory(Path.GetDirectoryName(path)!);
            File.WriteAllText(path, file.Content);
        }
    }
}

/// <summary>
/// Turns a validated <see cref="SystemTopology"/> into Dapr components and runtime config
/// for the local run profile: pub/sub backed by Redis Streams, file bindings anchored to the
/// SystemHost directory. Output order is deterministic.
/// </summary>
public static class TopologyGenerator
{
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Generates local artifacts, including validated development mock endpoints when declared.</summary>
    /// <param name="topology">The validated topology.</param>
    /// <param name="development">The optional validated development substitutions.</param>
    public static GeneratedArtifacts Generate(SystemTopology topology, DevelopmentManifest development)
    {
        ArgumentNullException.ThrowIfNull(topology);
        ArgumentNullException.ThrowIfNull(development);
        var files = new List<GeneratedFile>();

        foreach (var topic in topology.Topics.Select(t => t.PubSubName).Distinct(StringComparer.Ordinal))
        {
            files.Add(PubSubComponent(topic, topology));
        }

        // Local runs resolve every connector to localstorage, so the declared transport is
        // deliberately not consulted here: the placeholder default transport must not block
        // F5. Deployment generation is where an unresolved transport must hard-fail.
        foreach (var connector in topology.Connectors)
        {
            var resolution = development.Files.SingleOrDefault(file => file.ConnectorName == connector.Name);
            if (resolution is null)
            {
                throw new InvalidOperationException($"Connector '{connector.Name}' has no local file resolution in the development manifest.");
            }

            files.Add(BindingComponent(connector, resolution));
        }

        foreach (var mock in development.Mocks)
        {
            var service = topology.Services.Single(service => service.AppId == mock.AppId);
            files.Add(HttpEndpoint(mock, service));
        }

        foreach (var component in topology.Components)
        {
            files.Add(ComponentConfig(topology.SystemName, component));
        }

        return new GeneratedArtifacts(files);
    }

    private static GeneratedFile PubSubComponent(string pubSubName, SystemTopology topology)
    {
        var scopes = topology.Components
            .Where(c => c.Subscribes.Any(s => s.PubSubName == pubSubName) || c.Publishes.Any(p => p.PubSubName == pubSubName))
            .Select(c => c.Name)
            .OrderBy(n => n, StringComparer.Ordinal);

        // Redis Streams with consumer groups: an unacked or RETRY'd message is redelivered
        // after the component's redeliverInterval instead of being dropped. Port 6380 because
        // `dapr init` publishes its own dapr_redis on the host's 6379.
        var metadata = new[]
        {
            ("redisHost", "localhost:6380"),
        };
        var yaml = DaprYaml.Component(pubSubName, "pubsub.redis", metadata, scopes);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{pubSubName}.yaml", yaml);
    }

    private static GeneratedFile BindingComponent(ConnectorResource connector, ConnectorFileResolution resolution)
    {
        // Local runs resolve every connector to a localstorage folder. The manifest path is
        // already absolute (anchored at the SystemHost directory); artifacts land in per-run
        // temp dirs and the sidecar's cwd is not guaranteed, so an absolute path is required.
        var metadata = new List<(string, string)> { ("rootPath", resolution.RootPath) };
        var yaml = DaprYaml.Component(
            connector.DaprComponentName, "bindings.localstorage", metadata, connector.UsedBy);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{connector.DaprComponentName}.yaml", yaml);
    }

    private static GeneratedFile HttpEndpoint(OpenApiMock mock, ServiceResource service)
    {
        var yaml = DaprYaml.HttpEndpoint(mock.AppId, mock.BaseUri.AbsoluteUri, service.Consumers);
        return new GeneratedFile($"{GeneratedArtifacts.ComponentsDir}/{mock.AppId}.yaml", yaml);
    }

    private static GeneratedFile ComponentConfig(string systemName, ComponentModel component)
    {
        var config = new
        {
            Intropy = new
            {
                System = systemName,
                Component = component.Name,
                Kind = component.Kind.ToString(),
                Subscribes = component.Subscribes.Select(s => new { s.PubSubName, s.TopicName }),
                Publishes = component.Publishes.Select(p => new { p.Port, p.PubSubName, p.TopicName }),
                Connectors = component.Connectors.Select(c => new
                {
                    c.ConnectorName,
                    Direction = c.Direction.ToString(),
                    DaprComponent = $"binding.{c.ConnectorName}",
                }),
                Uses = component.Uses,
            },
        };

        var json = JsonSerializer.Serialize(config, s_json);
        return new GeneratedFile($"{GeneratedArtifacts.ConfigDir}/{component.Name}.intropy.json", json);
    }
}

/// <summary>Minimal, deterministic emitter for Dapr <c>Component</c> YAML.</summary>
internal static class DaprYaml
{
    public static string HttpEndpoint(string name, string baseUrl, IEnumerable<string> scopes)
    {
        var sb = new StringBuilder();
        sb.Append("apiVersion: dapr.io/v1alpha1\n");
        sb.Append("kind: HTTPEndpoint\n");
        sb.Append("metadata:\n");
        sb.Append("  name: ").Append(Quote(name)).Append('\n');
        sb.Append("spec:\n");
        sb.Append("  baseUrl: ").Append(Quote(baseUrl)).Append('\n');
        sb.Append("scopes:\n");
        foreach (var scope in scopes.OrderBy(scope => scope, StringComparer.Ordinal))
        {
            sb.Append("- ").Append(Quote(scope)).Append('\n');
        }

        return sb.ToString();
    }

    public static string Component(
        string name,
        string type,
        IEnumerable<(string Key, string Value)> metadata,
        IEnumerable<string> scopes)
    {
        var meta = metadata.ToList();
        var scopeList = scopes.ToList();

        var sb = new StringBuilder();
        sb.Append("apiVersion: dapr.io/v1alpha1\n");
        sb.Append("kind: Component\n");
        sb.Append("metadata:\n");
        sb.Append("  name: ").Append(Quote(name)).Append('\n');
        sb.Append("spec:\n");
        sb.Append("  type: ").Append(Quote(type)).Append('\n');
        sb.Append("  version: v1\n");
        if (meta.Count == 0)
        {
            sb.Append("  metadata: []\n");
        }
        else
        {
            sb.Append("  metadata:\n");
            foreach (var (key, value) in meta)
            {
                sb.Append("  - name: ").Append(Quote(key)).Append('\n');
                sb.Append("    value: ").Append(Quote(value)).Append('\n');
            }
        }

        if (scopeList.Count > 0)
        {
            sb.Append("scopes:\n");
            foreach (var scope in scopeList)
            {
                sb.Append("- ").Append(Quote(scope)).Append('\n');
            }
        }

        return sb.ToString();
    }

    private static string Quote(string value) =>
        $"\"{value.Replace("\\", "\\\\", StringComparison.Ordinal).Replace("\"", "\\\"", StringComparison.Ordinal)}\"";
}

using System.Reflection;
using System.Text.Json;
using System.Text.Json.Serialization;
using Intropy.Topology;
using Intropy.Topology.Model;

namespace Intropy.Topology.Generation;

/// <summary>
/// The non-Aspire backend: the <c>check</c>, <c>graph</c>, and <c>generate</c> CLI verbs over a
/// discovered system. F5 (the Aspire backend) and these verbs consume the same discovered truth.
/// </summary>
public static class IntropyGenerate
{
    private static readonly JsonSerializerOptions s_json = new()
    {
        WriteIndented = true,
        PropertyNamingPolicy = JsonNamingPolicy.CamelCase,
        DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull,
    };

    /// <summary>Runs a generation CLI verb against the system discovered in <paramref name="assembly"/>.</summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line arguments; <c>args[0]</c> is the verb (check | graph | generate).</param>
    /// <returns>A process exit code.</returns>
    public static Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        var verb = args.Length > 0 ? args[0] : "check";
        return Task.FromResult(verb switch
        {
            "check" => Check(assembly),
            "graph" => Graph(assembly, args),
            "generate" => Generate(assembly, args),
            _ => Unknown(verb),
        });
    }

    private static int Check(Assembly assembly)
    {
        try
        {
            var discovered = SystemDiscovery.Discover(assembly);
            DevelopmentDiscovery.Discover(assembly, discovered.Topology, Directory.GetCurrentDirectory());
            Console.WriteLine($"ok: '{discovered.Topology.SystemName}' is valid ({discovered.Topology.Components.Count} components).");
            return 0;
        }
        catch (Exception ex) when (ex is TopologyValidationException or DevelopmentValidationException or InvalidOperationException)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Graph(Assembly assembly, string[] args)
    {
        try
        {
            // Tolerant discovery: a partially built system (one-sided topics) must still be
            // inspectable. Warnings go to stderr so stdout stays pure JSON.
            var topology = SystemDiscovery.DiscoverTolerant(assembly, out var diagnostics).Topology;
            foreach (var diagnostic in diagnostics)
            {
                var severity = diagnostic.Severity == DiagnosticSeverity.Warning ? "warning" : "error";
                Console.Error.WriteLine($"{severity}: {diagnostic.Message}");
            }

            var development = args.Contains("--development", StringComparer.Ordinal)
                ? DevelopmentDiscovery.Discover(assembly, topology, Directory.GetCurrentDirectory())
                : null;
            Console.WriteLine(JsonSerializer.Serialize(GraphDocument.From(topology, development), s_json));
            return 0;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    /// <summary>Maps the validated internal model to the topology.intropy.io/v1 interchange contract.</summary>
    private sealed record GraphDocument(
        string ApiVersion,
        string Kind,
        string System,
        IReadOnlyList<GraphComponent>? Components,
        IReadOnlyList<GraphTopic>? Topics,
        IReadOnlyList<GraphConnector>? Connectors,
        IReadOnlyList<GraphService>? Services,
        GraphDevelopment? Development)
    {
        public static GraphDocument From(SystemTopology topology, DevelopmentManifest? development) => new(
            "topology.intropy.io/v1",
            "SystemTopology",
            topology.SystemName,
            Optional(topology.Components.Select(GraphComponent.From)),
            Optional(topology.Topics.Select(GraphTopic.From)),
            Optional(topology.Connectors.Select(GraphConnector.From)),
            Optional(topology.Services.Select(GraphService.From)),
            development is null ? null : GraphDevelopment.From(development));
    }

    private sealed record GraphDevelopment(
        IReadOnlyList<GraphMock>? Mocks,
        IReadOnlyList<GraphFileConnector>? Files)
    {
        public static GraphDevelopment From(DevelopmentManifest development) => new(
            Optional(development.Mocks.Select(GraphMock.From)),
            Optional(development.Files.Select(GraphFileConnector.From)));
    }

    private sealed record GraphMock(string AppId, string Artifact, string Title, string Version, string BaseUri)
    {
        public static GraphMock From(OpenApiMock mock) => new(
            mock.AppId, mock.ArtifactPath, mock.Title, mock.Version, mock.BaseUri.AbsoluteUri);
    }

    private sealed record GraphFileConnector(string Connector, string RootPath)
    {
        public static GraphFileConnector From(ConnectorFileResolution file) => new(file.ConnectorName, file.RootPath);
    }

    private sealed record GraphComponent(
        string Name,
        string Kind,
        IReadOnlyList<GraphTopicReference>? Subscribes,
        IReadOnlyList<GraphPublication>? Publishes,
        IReadOnlyList<GraphConnectorUse>? Connectors,
        IReadOnlyList<string>? Uses)
    {
        public static GraphComponent From(ComponentModel component) => new(
            component.Name,
            KebabCase(component.Kind.ToString()),
            Optional(component.Subscribes.Select(t => new GraphTopicReference(t.PubSubName, t.TopicName))),
            Optional(component.Publishes.Select(p => new GraphPublication(
                p.Port == "default" ? null : p.Port, p.PubSubName, p.TopicName))),
            Optional(component.Connectors.Select(c => new GraphConnectorUse(
                c.ConnectorName, Direction(c.Direction)))),
            Optional(component.Uses));
    }

    private sealed record GraphTopicReference(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphPublication(
        string? Port,
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic);

    private sealed record GraphConnectorUse(string Connector, string Direction);

    private sealed record GraphTopic(
        [property: JsonPropertyName("pubsub")] string PubSub,
        string Topic,
        string Contract,
        IReadOnlyList<string>? Publishers,
        IReadOnlyList<string>? Subscribers)
    {
        public static GraphTopic From(TopicResource topic) => new(
            topic.PubSubName,
            topic.TopicName,
            topic.ContractTypeName,
            Optional(topic.Publishers),
            Optional(topic.Subscribers));
    }

    private sealed record GraphConnector(
        string Name,
        IReadOnlyList<string>? Directions,
        IReadOnlyList<string>? UsedBy)
    {
        public static GraphConnector From(ConnectorResource connector) => new(
            connector.Name,
            Optional(connector.Directions.Select(Direction)),
            Optional(connector.UsedBy));
    }

    private sealed record GraphService(string AppId, IReadOnlyList<string>? Consumers)
    {
        public static GraphService From(ServiceResource service) => new(service.AppId, Optional(service.Consumers));
    }

    private static T[]? Optional<T>(IEnumerable<T> values)
    {
        var array = values.ToArray();
        return array.Length > 0 ? array : null;
    }

    private static string Direction(ConnectorDirection direction) =>
        direction == ConnectorDirection.In ? "in" : "out";

    private static string KebabCase(string pascal)
    {
        var builder = new System.Text.StringBuilder(pascal.Length + 4);
        foreach (var c in pascal)
        {
            if (char.IsUpper(c) && builder.Length > 0)
            {
                builder.Append('-');
            }

            builder.Append(char.ToLowerInvariant(c));
        }

        return builder.ToString();
    }

    private static int Generate(Assembly assembly, string[] args)
    {
        try
        {
            var directory = args.Skip(1).FirstOrDefault(a => !a.StartsWith('-')) ?? "./out";
            var discovered = SystemDiscovery.Discover(assembly);
            var development = DevelopmentDiscovery.Discover(assembly, discovered.Topology, Directory.GetCurrentDirectory());
            var artifacts = TopologyGenerator.Generate(discovered.Topology, development);
            artifacts.WriteTo(directory);

            Console.WriteLine($"generated {artifacts.Files.Count} files to '{directory}':");
            foreach (var file in artifacts.Files)
            {
                Console.WriteLine($"  {file.RelativePath}");
            }

            return 0;
        }
        catch (Exception ex) when (ex is TopologyValidationException or DevelopmentValidationException or InvalidOperationException)
        {
            Console.Error.WriteLine($"error: {ex.Message}");
            return 1;
        }
    }

    private static int Unknown(string verb)
    {
        Console.Error.WriteLine($"unknown command '{verb}'. Expected: check | graph | generate.");
        return 2;
    }
}

using System.Reflection;
using System.Text.RegularExpressions;
using Intropy.Topology.Model;
using Microsoft.OpenApi;
using Microsoft.OpenApi.Reader;
using Microsoft.OpenApi.YamlReader;

namespace Intropy.Topology.Generation;

/// <summary>Declares local development substitutions for a SystemHost topology.</summary>
public interface IDevelopmentDefinition
{
    /// <summary>Records local development substitutions.</summary>
    /// <param name="development">The builder scoped to the validated system topology.</param>
    void Define(DevelopmentBuilder development);
}

/// <summary>Records OpenAPI-backed local service mocks. Not thread-safe.</summary>
public sealed class DevelopmentBuilder
{
    private readonly SystemTopology _topology;
    private readonly string _root;
    private readonly List<MockDeclaration> _mocks = [];
    private readonly List<FileDeclaration> _files = [];

    internal DevelopmentBuilder(SystemTopology topology, string root)
    {
        _topology = topology;
        _root = Path.GetFullPath(root);
    }

    /// <summary>Declares a local mock for a service used by this topology.</summary>
    /// <param name="service">The platform-service identity to resolve locally.</param>
    public MockBuilder Mock(ServiceRef service)
    {
        ArgumentNullException.ThrowIfNull(service);
        if (!_topology.Services.Any(candidate => candidate.AppId == service.AppId))
        {
            throw new DevelopmentValidationException($"Service '{service.AppId}' is not used by the system topology.");
        }

        if (_mocks.Any(candidate => candidate.AppId == service.AppId))
        {
            throw new DevelopmentValidationException($"Service '{service.AppId}' has more than one mock declaration.");
        }

        var declaration = new MockDeclaration(service.AppId);
        _mocks.Add(declaration);
        return new MockBuilder(declaration);
    }

    /// <summary>Declares the local file resolution for a connector used by this topology.</summary>
    /// <param name="connector">The connector to resolve locally.</param>
    public FileBuilder Files(ConnectorRef connector)
    {
        ArgumentNullException.ThrowIfNull(connector);
        if (!_topology.Connectors.Any(candidate => candidate.Name == connector.Name))
        {
            throw new DevelopmentValidationException($"Connector '{connector.Name}' is not used by the system topology.");
        }

        if (_files.Any(candidate => candidate.ConnectorName == connector.Name))
        {
            throw new DevelopmentValidationException($"Connector '{connector.Name}' has more than one file resolution.");
        }

        var declaration = new FileDeclaration(connector.Name);
        _files.Add(declaration);
        return new FileBuilder(declaration);
    }

    internal DevelopmentManifest Build()
    {
        var mocks = _mocks.Select(mock => OpenApiArtifact.Inspect(_root, mock)).ToArray();
        var duplicateIdentity = mocks.GroupBy(mock => (mock.Title, mock.Version))
            .FirstOrDefault(group => group.Select(mock => mock.AppId).Distinct(StringComparer.Ordinal).Count() > 1);
        if (duplicateIdentity is not null)
        {
            throw new DevelopmentValidationException(
                $"Mocks for services '{string.Join("', '", duplicateIdentity.Select(mock => mock.AppId))}' resolve to the same Microcks identity '{duplicateIdentity.Key.Title}' version '{duplicateIdentity.Key.Version}'.");
        }

        var unresolved = _topology.Connectors
            .Where(connector => !_files.Any(file => file.ConnectorName == connector.Name))
            .Select(connector => connector.Name)
            .OrderBy(name => name, StringComparer.Ordinal)
            .ToArray();
        if (unresolved.Length > 0)
        {
            throw new DevelopmentValidationException(
                $"Connectors '{string.Join("', '", unresolved)}' have no local file resolution.");
        }

        var files = _files.Select(file => FileRootPath.Inspect(_root, file)).ToArray();
        return new DevelopmentManifest(
            mocks.OrderBy(mock => mock.AppId, StringComparer.Ordinal).ToArray(),
            files.OrderBy(file => file.ConnectorName, StringComparer.Ordinal).ToArray());
    }

    /// <summary>Configures the OpenAPI artifact for one service mock.</summary>
    public sealed class MockBuilder
    {
        private readonly MockDeclaration _declaration;
        internal MockBuilder(MockDeclaration declaration) => _declaration = declaration;

        /// <summary>Uses a self-contained OpenAPI 3.0.x document relative to the SystemHost directory.</summary>
        /// <param name="path">The relative contract path.</param>
        public void FromOpenApi(string path)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(path);
            if (_declaration.Path is not null)
            {
                throw new DevelopmentValidationException($"Service '{_declaration.AppId}' has more than one OpenAPI artifact.");
            }

            _declaration.Path = path;
        }
    }

    /// <summary>Configures the local root path for one connector file resolution.</summary>
    public sealed class FileBuilder
    {
        private readonly FileDeclaration _declaration;
        internal FileBuilder(FileDeclaration declaration) => _declaration = declaration;

        /// <summary>Reads and writes files in a folder relative to the SystemHost directory.</summary>
        /// <param name="path">The relative folder path.</param>
        public void RootPath(string path)
        {
            ArgumentException.ThrowIfNullOrWhiteSpace(path);
            if (_declaration.Path is not null)
            {
                throw new DevelopmentValidationException($"Connector '{_declaration.ConnectorName}' has more than one root path.");
            }

            _declaration.Path = path;
        }
    }

    internal sealed class MockDeclaration(string appId)
    {
        public string AppId { get; } = appId;
        public string? Path { get; set; }
    }

    internal sealed class FileDeclaration(string connectorName)
    {
        public string ConnectorName { get; } = connectorName;
        public string? Path { get; set; }
    }
}

/// <summary>Validated development substitutions consumed by generation and local runtime backends.</summary>
public sealed record DevelopmentManifest(IReadOnlyList<OpenApiMock> Mocks, IReadOnlyList<ConnectorFileResolution> Files);

/// <summary>One connector's validated local file resolution.</summary>
public sealed record ConnectorFileResolution(string ConnectorName, string RootPath);

/// <summary>One OpenAPI-backed platform-service mock with a verified Microcks identity.</summary>
public sealed record OpenApiMock(string AppId, string ArtifactPath, string Title, string Version)
{
    /// <summary>The local Microcks REST base URI, with title and version escaped as individual path segments.</summary>
    public Uri BaseUri => new($"http://localhost:8585/rest/{Uri.EscapeDataString(Title)}/{Uri.EscapeDataString(Version)}", UriKind.Absolute);
}

/// <summary>Thrown when a development definition or its artifacts are invalid.</summary>
public sealed class DevelopmentValidationException : InvalidOperationException
{
    /// <summary>Creates an empty validation exception.</summary>
    public DevelopmentValidationException() { }

    /// <summary>Creates a validation exception with a focused diagnostic.</summary>
    public DevelopmentValidationException(string message) : base(message) { }

    /// <summary>Creates a validation exception with its underlying cause.</summary>
    public DevelopmentValidationException(string message, Exception innerException) : base(message, innerException) { }
}

/// <summary>Discovers the optional development definition associated with a SystemHost assembly.</summary>
public static class DevelopmentDiscovery
{
    /// <summary>Discovers and validates zero or one development definition.</summary>
    public static DevelopmentManifest Discover(Assembly assembly, SystemTopology topology, string root)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        var candidates = assembly.GetTypes()
            .Where(type => type is { IsAbstract: false, IsInterface: false } && typeof(IDevelopmentDefinition).IsAssignableFrom(type))
            .ToArray();
        if (candidates.Length > 1)
        {
            throw new DevelopmentValidationException(
                $"Multiple {nameof(IDevelopmentDefinition)} types were found: {string.Join(", ", candidates.Select(type => type.FullName))}. Exactly zero or one is required.");
        }

        if (candidates.Length == 0)
        {
            return new DevelopmentManifest([], []);
        }

        var builder = new DevelopmentBuilder(topology, root);
        ((IDevelopmentDefinition)Activator.CreateInstance(candidates[0])!).Define(builder);
        return builder.Build();
    }
}

internal static class FileRootPath
{
    public static ConnectorFileResolution Inspect(string root, DevelopmentBuilder.FileDeclaration declaration)
    {
        var connectorName = declaration.ConnectorName;
        var relativePath = declaration.Path;
        if (relativePath is null)
        {
            throw new DevelopmentValidationException($"File resolution for connector '{connectorName}' does not declare a root path.");
        }

        var rootPath = ResolveDirectory(root, $"SystemHost directory '{root}' cannot be resolved");
        var folderPath = Path.GetFullPath(Path.Combine(rootPath, relativePath));
        if (Directory.Exists(folderPath))
        {
            folderPath = ResolveDirectory(folderPath, $"File resolution '{relativePath}' for connector '{connectorName}' cannot be resolved");
        }

        if (!folderPath.StartsWith(rootPath + Path.DirectorySeparatorChar, StringComparison.Ordinal) && !string.Equals(folderPath, rootPath, StringComparison.Ordinal))
        {
            throw new DevelopmentValidationException($"File resolution '{relativePath}' for connector '{connectorName}' escapes the SystemHost directory.");
        }

        return new ConnectorFileResolution(connectorName, folderPath);
    }

    private static string ResolveDirectory(string path, string error)
    {
        try
        {
            return Path.GetFullPath(new DirectoryInfo(path).ResolveLinkTarget(returnFinalTarget: true)?.FullName ?? path);
        }
        catch (IOException ex)
        {
            throw new DevelopmentValidationException($"{error}: {ex.Message}", ex);
        }
    }
}

internal static class OpenApiArtifact
{
    private static readonly Regex s_openApiVersion = new("^\\s*openapi\\s*:\\s*['\\\"]?(?<version>[^'\\\"\\s#]+)", RegexOptions.Multiline | RegexOptions.CultureInvariant);
    private static readonly Regex s_externalRef = new("^\\s*(?:\\\"?\\$ref\\\"?\\s*:)\\s*['\\\"]?(?!#)(?<reference>\\S+)", RegexOptions.Multiline | RegexOptions.CultureInvariant);

    public static OpenApiMock Inspect(string root, DevelopmentBuilder.MockDeclaration declaration)
    {
        var appId = declaration.AppId;
        var relativePath = declaration.Path;
        if (relativePath is null)
        {
            throw new DevelopmentValidationException($"Mock for service '{appId}' does not declare an OpenAPI artifact.");
        }

        var rootPath = Path.GetFullPath(root);
        try
        {
            rootPath = Path.GetFullPath(new DirectoryInfo(rootPath).ResolveLinkTarget(returnFinalTarget: true)?.FullName ?? rootPath);
        }
        catch (IOException ex)
        {
            throw new DevelopmentValidationException($"SystemHost directory '{root}' cannot be resolved: {ex.Message}", ex);
        }

        var artifactPath = Path.GetFullPath(Path.Combine(rootPath, relativePath));
        if (!artifactPath.StartsWith(rootPath + Path.DirectorySeparatorChar, StringComparison.Ordinal) && !string.Equals(artifactPath, rootPath, StringComparison.Ordinal))
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' escapes the SystemHost directory.");
        }

        try
        {
            artifactPath = Path.GetFullPath(new FileInfo(artifactPath).ResolveLinkTarget(returnFinalTarget: true)?.FullName ?? artifactPath);
        }
        catch (IOException ex)
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' cannot be resolved: {ex.Message}");
        }

        if (!artifactPath.StartsWith(rootPath + Path.DirectorySeparatorChar, StringComparison.Ordinal))
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' escapes the SystemHost directory through a symlink.");
        }

        string text;
        try
        {
            text = File.ReadAllText(artifactPath);
        }
        catch (Exception ex) when (ex is IOException or UnauthorizedAccessException)
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' cannot be read: {ex.Message}");
        }

        var version = s_openApiVersion.Match(text).Groups["version"].Value;
        if (!Version.TryParse(version, out var parsedVersion) || parsedVersion.Major != 3 || parsedVersion.Minor != 0)
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' must be an OpenAPI 3.0.x document.");
        }

        if (s_externalRef.IsMatch(text))
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' contains an external $ref.");
        }

        try
        {
            var settings = new OpenApiReaderSettings();
            settings.AddYamlReader();
            var document = OpenApiDocument.LoadAsync(artifactPath, settings).GetAwaiter().GetResult().Document
                ?? throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' could not be parsed.");
            var info = document.Info;
            if (info is null || string.IsNullOrWhiteSpace(info.Title) || string.IsNullOrWhiteSpace(info.Version))
            {
                throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' must define non-empty info.title and info.version.");
            }

            return new OpenApiMock(appId, artifactPath, info.Title, info.Version);
        }
        catch (DevelopmentValidationException)
        {
            throw;
        }
        catch (Exception ex)
        {
            throw new DevelopmentValidationException($"Mock artifact '{relativePath}' for service '{appId}' is not a valid OpenAPI document: {ex.Message}");
        }
    }
}

using System.Net;
using System.Net.Sockets;
using System.Reflection;
using Aspire.Hosting;
using Aspire.Hosting.ApplicationModel;
using CommunityToolkit.Aspire.Hosting.Dapr;
using Intropy.Topology.Generation;
using Intropy.Topology.Model;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.DependencyInjection.Extensions;

namespace Intropy.Topology.Aspire;

/// <summary>
/// Runs a discovered topology as a local Aspire application with Dapr sidecars. Components
/// start subscribers before publishers when the topic graph is acyclic.
/// </summary>
public static class IntropyAspire
{
    /// <summary>
    /// Fixed host port for the local Redis backend (generated pub/sub YAML points here).
    /// 6380 rather than the Redis default: `dapr init` publishes its own dapr_redis on 6379.
    /// </summary>
    internal const int RedisPort = 6380;

    /// <summary>Fixed host port for the local Microcks Uber backend.</summary>
    internal const int MicrocksPort = 8585;

    /// <summary>
    /// Discovers the system in <paramref name="assembly"/>, generates its artifacts to a temp folder,
    /// builds the Aspire resource graph, and runs it. Requires Docker and the Dapr CLI to be present.
    /// </summary>
    /// <param name="assembly">The assembly declaring the <see cref="ISystemDefinition"/>.</param>
    /// <param name="args">Command-line args passed through to the distributed application builder.</param>
    /// <returns>A process exit code.</returns>
    public static async Task<int> RunAsync(Assembly assembly, string[] args)
    {
        ArgumentNullException.ThrowIfNull(assembly);
        ArgumentNullException.ThrowIfNull(args);

        try
        {
            var discovered = SystemDiscovery.Discover(assembly);
            var builder = DistributedApplication.CreateBuilder(args);
            var development = DevelopmentDiscovery.Discover(assembly, discovered.Topology, builder.AppHostDirectory);

            var generatedRoot = Path.Combine(
                Path.GetTempPath(), "intropy-aspire", $"{discovered.Topology.SystemName}-{Guid.NewGuid():N}");
            TopologyGenerator.Generate(discovered.Topology, development).WriteTo(generatedRoot);

            Apply(builder, discovered.Topology, generatedRoot, development);

            var app = builder.Build();
            await app.RunAsync().ConfigureAwait(false);
            return 0;
        }
        catch (Exception ex) when (ex is TopologyValidationException or DevelopmentValidationException or InvalidOperationException)
        {
            await Console.Error.WriteLineAsync($"error: {ex.Message}").ConfigureAwait(false);
            return 1;
        }
    }

    /// <summary>
    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
    /// </summary>
    internal static void Apply(
        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot) =>
        Apply(builder, topology, generatedRoot, new DevelopmentManifest([], []));

    internal static void Apply(
        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot, DevelopmentManifest development)
    {
        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);

        // A plain Redis container rather than AddRedis: the generated pub/sub YAML speaks
        // passwordless to localhost:6380, while AddRedis injects a generated password.
        EnsureHostPortAvailable(RedisPort);
        var redis = builder
            .AddContainer("redis", "docker.io/library/redis", "7")
            .WithEndpoint(port: RedisPort, targetPort: 6379);
        // Everything a sidecar dials during component init. Sidecars must wait for Redis to be
        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
        // a still-starting backend kills the sidecar. localhost:6380 is DCP's endpoint proxy,
        // which accepts connections from host start, so the probe must demand a PONG rather
        // than settle for an open socket.
        var redisReadiness = new TcpReadyHealthCheck("localhost", RedisPort, TcpReadyHealthCheck.RedisHandshake);
        WithTcpReadiness(builder, redis, redisReadiness);

        MockReadiness? mockReadiness = null;
        IResourceBuilder<ContainerResource>? microcks = null;
        if (development.Mocks.Count > 0)
        {
            EnsureHostPortAvailable(MicrocksPort, "Microcks");
            microcks = builder
                .AddContainer("microcks", "quay.io/microcks/microcks-uber", "1.13.0")
                .WithEndpoint(name: "http", scheme: "http", port: MicrocksPort, targetPort: 8080)
                .WithHttpHealthCheck("/api/health");
            mockReadiness = new MockReadiness(development);
            builder.Services.AddSingleton(development);
            builder.Services.AddSingleton(mockReadiness);
            builder.Services.AddHttpClient(nameof(MicrocksImporter));
            builder.Services.AddSingleton<MicrocksImporter>();
            microcks.OnResourceReady(async (_, evt, cancellationToken) =>
            {
                var importer = evt.Services.GetRequiredService<MicrocksImporter>();
                await importer.ImportAsync(cancellationToken).ConfigureAwait(false);
            });
        }

        // Filled after the component loop; the hook closure only reads it at runtime.
        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);

        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
        // every backend port answers and, for publishers, until every subscriber sidecar is running.
        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
        {
            var isSidecar = DaprSidecarIdentity.IsCli(evt.Resource.Name);
            var componentName = isSidecar
                ? evt.Resource.Name[..^"-dapr-cli".Length]
                : evt.Resource.Name;
            var component = topology.Components.SingleOrDefault(candidate => candidate.Name == componentName);
            if (component is null)
            {
                return;
            }

            if (mockReadiness is not null)
            {
                await mockReadiness.WaitForAsync(component.Uses, TimeSpan.FromMinutes(3), cancellationToken)
                    .ConfigureAwait(false);
            }

            if (!isSidecar)
            {
                return;
            }

            await redisReadiness.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken)
                .ConfigureAwait(false);
            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
            {
                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
                foreach (var sidecar in subscriberSidecars)
                {
                    await notifications
                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
                        .ConfigureAwait(false);
                }
            }
        });

        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
        var unresolved = new List<string>();
        foreach (var component in topology.Components)
        {
            // Each integration gets its own staged component set: its local files plus the
            // generated system overlay, at a stable inspectable path under obj/.
            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);

            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
            if (!File.Exists(projectPath))
            {
                unresolved.Add($"{component.Name} (expected {projectPath})");
                continue;
            }

            var project = builder.AddProject(component.Name, projectPath);
            // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it
            // every Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
            project = project.WithHttpEndpoint();

            Wire(project, component, stagedPath, configDir, redis, microcks);
            resources[component.Name] = project;
            waiters[component.Name] = dependency => project.WaitFor(dependency);
        }

        RegisterDaprSidecarRecovery(builder, redisReadiness);

        if (unresolved.Count > 0)
        {
            throw new InvalidOperationException(
                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
                "Create the project next to the SystemHost.");
        }

        // Subscribers start first, so a publisher's first message finds a registered
        // subscription. Nobody declares this: it is derived from who publishes and who
        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
        // rather than deadlock.
        var precedence = SubscriberPrecedence(topology);
        if (HasCycle(precedence))
        {
            Console.Error.WriteLine(
                "intropy: the topology's topics form a publish/subscribe cycle; " +
                "skipping subscriber-first startup ordering.");
            return;
        }

        foreach (var (publisher, subscribers) in precedence)
        {
            if (!waiters.TryGetValue(publisher, out var wait))
            {
                continue;
            }

            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
            foreach (var subscriber in materialized)
            {
                wait(resources[subscriber]);
            }

            if (materialized.Length > 0)
            {
                sidecarWaits[DaprSidecarIdentity.CliName(publisher)] =
                    [.. materialized.Select(DaprSidecarIdentity.CliName)];
            }
        }
    }

    /// <summary>
    /// Registers recovery for components' Dapr sidecars. The normal pre-start gate
    /// prevents the common race; recovery covers the remaining interval where a backend passes
    /// TCP readiness but daprd's component initialization still fails.
    /// </summary>
    private static void RegisterDaprSidecarRecovery(
        IDistributedApplicationBuilder builder, IBackendReadiness backendReadiness)
    {
        builder.Services.TryAddSingleton(TimeProvider.System);
        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
        builder.Services.AddSingleton<IResourceStateMonitor, AspireResourceStateMonitor>();
        builder.Services.AddSingleton<IBackendReadiness>(backendReadiness);
        builder.Services.AddSingleton<DaprSidecarRecovery>();
        builder.Services.AddHostedService(sp => sp.GetRequiredService<DaprSidecarRecovery>());
    }

    /// <summary>
    /// Which components each publisher must wait for: every subscriber of every topic it
    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
    /// </summary>
    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
    {
        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
        foreach (var topic in topology.Topics)
        {
            foreach (var publisher in topic.Publishers)
            {
                foreach (var subscriber in topic.Subscribers)
                {
                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
                    {
                        continue;
                    }

                    if (!precedence.TryGetValue(publisher, out var subscribers))
                    {
                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
                    }

                    subscribers.Add(subscriber);
                }
            }
        }

        return precedence;
    }

    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
    {
        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done

        bool Visit(string node)
        {
            if (state.TryGetValue(node, out var seen))
            {
                return seen == 1;
            }

            state[node] = 1;
            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
            {
                return true;
            }

            state[node] = 2;
            return false;
        }

        return edges.Keys.Any(Visit);
    }

    private static void EnsureHostPortAvailable(int port, string backend = "Redis")
    {
        try
        {
            using var listener = new TcpListener(IPAddress.Loopback, port);
            listener.Start();
        }
        catch (SocketException ex)
        {
            throw new InvalidOperationException(
                $"{backend} requires host port {port}, but it is already in use. Stop the conflicting process and retry.", ex);
        }
    }

    private static void WithTcpReadiness(
        IDistributedApplicationBuilder builder,
        IResourceBuilder<ContainerResource> container,
        TcpReadyHealthCheck readiness)
    {
        var key = $"{container.Resource.Name}-tcp-ready";
        builder.Services.AddHealthChecks().AddCheck(key, readiness);
        container.WithHealthCheck(key);
    }

    private static void Wire(
        IResourceBuilder<ProjectResource> project,
        ComponentModel component,
        string resourcesPath,
        string configDir,
        IResourceBuilder<ContainerResource> redis,
        IResourceBuilder<ContainerResource>? microcks)
    {
        project
            .WithDaprSidecar(sidecar =>
            {
                sidecar.WithOptions(new DaprSidecarOptions
                {
                    AppId = component.Name,
                    ResourcesPaths = [resourcesPath],
                });
                sidecar.WaitFor(redis);
            })
            .WithEnvironment("INTROPY__COMPONENT", component.Name)
            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"))
            .WaitFor(redis);
        if (microcks is not null && component.Uses.Count > 0)
        {
            project.WaitFor(microcks);
        }
    }
}

using System.Collections.Concurrent;
using Aspire.Hosting.ApplicationModel;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;

namespace Intropy.Topology.Aspire;

/// <summary>A resource-state update consumed by sidecar recovery.</summary>
internal sealed record ResourceStateUpdate(string ResourceName, string? State);

/// <summary>Streams Aspire resource state changes without exposing Aspire's event types.</summary>
internal interface IResourceStateMonitor
{
    IAsyncEnumerable<ResourceStateUpdate> WatchAsync(CancellationToken cancellationToken);
}

/// <summary>
/// The recovery service's view of the Aspire resource model: last known states plus start/wait
/// commands. A seam so behavior is unit-testable without DCP.
/// </summary>
internal interface IResourceLifecycle
{
    /// <summary>Maintains the last-known-state map; runs for the host's lifetime.</summary>
    Task WatchAsync(CancellationToken cancellationToken);

    /// <summary>Whether the resource can be started: never seen, or in a terminal state.
    /// A non-terminal state means a run is still in progress.</summary>
    bool IsStartable(string resourceName);

    /// <summary>Executes a resource command; false when the command fails or is unavailable.</summary>
    Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken);

    /// <summary>Waits for the resource to reach Running; false on timeout.</summary>
    Task<bool> WaitUntilRunningAsync(string resourceName, TimeSpan timeout, CancellationToken cancellationToken);
}

/// <summary>Production <see cref="IResourceLifecycle"/> over the Aspire services.</summary>
internal sealed class AspireResourceLifecycle(
    ResourceCommandService commands,
    ResourceNotificationService notifications) : IResourceLifecycle
{
    private readonly ConcurrentDictionary<string, string?> _states = new(StringComparer.Ordinal);

    public async Task WatchAsync(CancellationToken cancellationToken)
    {
        await foreach (var evt in notifications.WatchAsync(cancellationToken).ConfigureAwait(false))
        {
            _states[evt.Resource.Name] = evt.Snapshot.State?.Text;
        }
    }

    public bool IsStartable(string resourceName)
    {
        var state = _states.GetValueOrDefault(resourceName);
        return state is null || KnownResourceStates.TerminalStates.Contains(state, StringComparer.Ordinal);
    }

    public async Task<bool> ExecuteAsync(string resourceName, string commandName, CancellationToken cancellationToken)
    {
        try
        {
            var result = await commands
                .ExecuteCommandAsync(resourceName, commandName, cancellationToken)
                .ConfigureAwait(false);
            return result.Success;
        }
        catch (Exception) when (!cancellationToken.IsCancellationRequested)
        {
            // Command unavailable in the resource's current state, or the resource is
            // unknown — the caller decides whether to fall back or give up.
            return false;
        }
    }

    public async Task<bool> WaitUntilRunningAsync(
        string resourceName, TimeSpan timeout, CancellationToken cancellationToken)
    {
        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(timeout);
        try
        {
            await notifications
                .WaitForResourceAsync(resourceName, KnownResourceStates.Running, deadline.Token)
                .ConfigureAwait(false);
            return true;
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            return false;
        }
    }
}

/// <summary>Production resource-state monitor over Aspire notifications.</summary>
internal sealed class AspireResourceStateMonitor(ResourceNotificationService notifications) : IResourceStateMonitor
{
    public async IAsyncEnumerable<ResourceStateUpdate> WatchAsync(
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken)
    {
        await foreach (var update in notifications.WatchAsync(cancellationToken).ConfigureAwait(false))
        {
            yield return new ResourceStateUpdate(update.Resource.Name, update.Snapshot.State?.Text);
        }
    }
}

/// <summary>
/// Compatibility seam for the executable resource created by CommunityToolkit.Aspire.Hosting.Dapr 13.0.0.
/// The toolkit's public sidecar model does not expose this executable, so audit this convention when
/// upgrading the toolkit.
/// </summary>
internal static class DaprSidecarIdentity
{
    private const string CliSuffix = "-dapr-cli";

    public static string CliName(string componentName) => componentName + CliSuffix;

    public static bool IsCli(string resourceName) => resourceName.EndsWith(CliSuffix, StringComparison.Ordinal);
}

internal sealed class DaprSidecarRecovery(
    IResourceStateMonitor states,
    IResourceLifecycle lifecycle,
    IBackendReadiness backendReadiness,
    TimeProvider time,
    ILogger<DaprSidecarRecovery> logger) : BackgroundService
{
    private const int MaxAttemptsPerSidecar = 3;
    private static readonly TimeSpan s_backendReadyTimeout = TimeSpan.FromMinutes(3);

    // DCP reports an executable as Running the moment its process launches, not when it is
    // healthy — daprd lives ~1s before a fatal component-init exit. Only a stay in Running at
    // least this long counts as having actually run; a sidecar that legitimately completes
    // faster costs at most MaxAttemptsPerSidecar spurious restarts.
    private static readonly TimeSpan s_minHealthyRunningDuration = TimeSpan.FromSeconds(10);

    private readonly ConcurrentDictionary<string, int> _attempts = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<string, long> _runningSince = new(StringComparer.Ordinal);
    private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new(StringComparer.Ordinal);

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        try
        {
            await foreach (var update in states.WatchAsync(stoppingToken).ConfigureAwait(false))
            {
                await HandleStateUpdateAsync(update, stoppingToken).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
        {
            // Host shutdown.
        }
    }

    internal async Task HandleStateUpdateAsync(ResourceStateUpdate update, CancellationToken cancellationToken)
    {
        if (!DaprSidecarIdentity.IsCli(update.ResourceName))
        {
            return;
        }

        if (string.Equals(update.State, KnownResourceStates.Running, StringComparison.Ordinal))
        {
            // Overwrite (not TryAdd): after a recovery restart the fresh instance's clock must
            // start over, or its own early crash would be judged by the previous run's stamp.
            _runningSince[update.ResourceName] = time.GetTimestamp();
            return;
        }

        // Only a sustained stay in Running proves the sidecar initialized; a component-init
        // crash a moment after launch must still recover.
        var ranHealthily = _runningSince.TryGetValue(update.ResourceName, out var since)
            && time.GetElapsedTime(since) >= s_minHealthyRunningDuration;
        var failedBeforeRunning = string.Equals(update.State, KnownResourceStates.Finished, StringComparison.Ordinal)
            || string.Equals(update.State, KnownResourceStates.Exited, StringComparison.Ordinal);
        if (!string.Equals(update.State, KnownResourceStates.FailedToStart, StringComparison.Ordinal)
            && (!failedBeforeRunning || ranHealthily))
        {
            return;
        }

        var gate = _gates.GetOrAdd(update.ResourceName, _ => new SemaphoreSlim(1, 1));
        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
        {
            return;
        }

        try
        {
            var attempt = _attempts.AddOrUpdate(update.ResourceName, 1, (_, prior) => prior + 1);
            if (attempt > MaxAttemptsPerSidecar)
            {
                logger.LogError(
                    "intropy-dapr: {Sidecar} exhausted {MaxAttempts} recovery attempts; inspect its component configuration",
                    update.ResourceName, MaxAttemptsPerSidecar);
                return;
            }

            logger.LogWarning(
                "intropy-dapr: {Sidecar} terminated before completing component initialization; waiting for backends before recovery attempt {Attempt}/{MaxAttempts}",
                update.ResourceName, attempt, MaxAttemptsPerSidecar);
            await backendReadiness.WaitUntilReadyAsync(s_backendReadyTimeout, cancellationToken).ConfigureAwait(false);

            // FailedToStart normally accepts Restart. Start is a state-race fallback when DCP
            // has already moved the resource to a startable terminal state.
            var recovered = await lifecycle
                .ExecuteAsync(update.ResourceName, KnownResourceCommands.RestartCommand, cancellationToken)
                .ConfigureAwait(false)
                || await lifecycle
                    .ExecuteAsync(update.ResourceName, KnownResourceCommands.StartCommand, cancellationToken)
                    .ConfigureAwait(false);
            if (!recovered)
            {
                logger.LogWarning(
                    "intropy-dapr: recovery command for {Sidecar} was unavailable or failed (attempt {Attempt}/{MaxAttempts})",
                    update.ResourceName, attempt, MaxAttemptsPerSidecar);
            }
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            throw;
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "intropy-dapr: unable to recover {Sidecar}", update.ResourceName);
        }
        finally
        {
            gate.Release();
        }
    }
}

using System.Net.Http.Headers;
using System.Text.Json;
using Intropy.Topology.Generation;
using Microsoft.Extensions.Logging;

namespace Intropy.Topology.Aspire;

/// <summary>Service-specific readiness gates completed only after Microcks imports each contract.</summary>
internal sealed class MockReadiness(DevelopmentManifest development)
{
    private readonly Dictionary<string, TaskCompletionSource> _gates = development.Mocks.ToDictionary(
        mock => mock.AppId,
        _ => new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously),
        StringComparer.Ordinal);

    public async Task WaitForAsync(IEnumerable<string> appIds, TimeSpan timeout, CancellationToken cancellationToken)
    {
        var waits = appIds.Where(_gates.ContainsKey).Select(appId => _gates[appId].Task).ToArray();
        if (waits.Length == 0)
        {
            return;
        }

        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(timeout);
        await Task.WhenAll(waits).WaitAsync(deadline.Token).ConfigureAwait(false);
    }

    public void Complete(string appId) => _gates[appId].TrySetResult();

    public void Fail(string appId, Exception exception) => _gates[appId].TrySetException(exception);
}

/// <summary>Imports and verifies all local mock contracts before their consumers start.</summary>
internal sealed class MicrocksImporter(
    DevelopmentManifest development,
    MockReadiness readiness,
    IHttpClientFactory clients,
    ILogger<MicrocksImporter> logger)
{
    private static readonly TimeSpan s_timeout = TimeSpan.FromMinutes(3);

    internal async Task ImportAsync(CancellationToken cancellationToken)
    {
        var client = clients.CreateClient(nameof(MicrocksImporter));
        client.BaseAddress = new Uri("http://localhost:8585");
        foreach (var mock in development.Mocks)
        {
            try
            {
                await ImportAndVerifyAsync(client, mock, cancellationToken).ConfigureAwait(false);
                readiness.Complete(mock.AppId);
            }
            catch (Exception ex) when (!cancellationToken.IsCancellationRequested)
            {
                readiness.Fail(mock.AppId, new InvalidOperationException(
                    $"Microcks could not import or verify service '{mock.AppId}' from '{mock.ArtifactPath}'.", ex));
                logger.LogError(ex, "intropy-microcks: could not prepare {Service} from {Artifact}", mock.AppId, mock.ArtifactPath);
            }
        }
    }

    private static async Task ImportAndVerifyAsync(HttpClient client, OpenApiMock mock, CancellationToken cancellationToken)
    {
        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(s_timeout);
        while (true)
        {
            try
            {
                using var health = await client.GetAsync(new Uri("/api/health", UriKind.Relative), deadline.Token).ConfigureAwait(false);
                if (health.IsSuccessStatusCode)
                {
                    break;
                }
            }
            catch (HttpRequestException) when (!deadline.IsCancellationRequested)
            {
                // The published endpoint is available before the Uber process is ready.
            }

            await Task.Delay(TimeSpan.FromSeconds(1), deadline.Token).ConfigureAwait(false);
        }

        await using var stream = File.OpenRead(mock.ArtifactPath);
        using var content = new MultipartFormDataContent();
        using var file = new StreamContent(stream);
        file.Headers.ContentType = new MediaTypeHeaderValue("application/yaml");
        content.Add(file, "file", Path.GetFileName(mock.ArtifactPath));
        using var upload = await client.PostAsync(new Uri("/api/artifact/upload?mainArtifact=true", UriKind.Relative), content, deadline.Token).ConfigureAwait(false);
        if (upload.StatusCode != System.Net.HttpStatusCode.Created)
        {
            throw new InvalidOperationException($"Microcks artifact upload returned {(int)upload.StatusCode} ({upload.ReasonPhrase}).");
        }

        while (true)
        {
            using var response = await client.GetAsync(new Uri("/api/services?page=0&size=100", UriKind.Relative), deadline.Token).ConfigureAwait(false);
            response.EnsureSuccessStatusCode();
            await using var responseStream = await response.Content.ReadAsStreamAsync(deadline.Token).ConfigureAwait(false);
            using var services = await JsonDocument.ParseAsync(responseStream, cancellationToken: deadline.Token).ConfigureAwait(false);
            var matches = CountMatchingServices(services.RootElement, mock);
            if (matches == 1)
            {
                return;
            }

            if (matches > 1)
            {
                throw new InvalidOperationException("Microcks returned more than one matching REST service.");
            }

            await Task.Delay(TimeSpan.FromSeconds(1), deadline.Token).ConfigureAwait(false);
        }
    }

    internal static int CountMatchingServices(JsonElement root, OpenApiMock mock)
    {
        var entries = root;
        if (entries.ValueKind == JsonValueKind.Object && entries.TryGetProperty("content", out var contentProperty))
        {
            entries = contentProperty;
        }

        if (entries.ValueKind != JsonValueKind.Array)
        {
            throw new InvalidOperationException("Microcks services response was not an array.");
        }

        return entries.EnumerateArray().Count(service =>
            service.GetProperty("name").GetString() == mock.Title
            && service.GetProperty("version").GetString() == mock.Version
            && service.GetProperty("type").GetString() == "REST");
    }
}

namespace Intropy.Topology.Aspire;

/// <summary>
/// Stages the effective Dapr resource set for one integration. Local resources are copied first;
/// generated resources replace only an identical <c>(apiVersion, kind, metadata.name)</c> identity.
/// A generated HTTP endpoint is staged only for a component named in its scopes.
/// </summary>
internal static class ComponentOverlay
{
    /// <summary>Stages the component set and returns the staged directory.</summary>
    public static string Stage(string appHostDirectory, string componentName, string generatedComponentsDir)
    {
        var stagedDir = Path.Combine(appHostDirectory, "obj", "dapr-components", componentName);
        if (Directory.Exists(stagedDir))
        {
            Directory.Delete(stagedDir, recursive: true);
        }

        Directory.CreateDirectory(stagedDir);
        var stagedByName = new Dictionary<string, StagedResource>(StringComparer.Ordinal);
        CopyResources(ProjectConvention.LocalComponentsDir(appHostDirectory, componentName), stagedDir, stagedByName, componentName, generated: false);
        CopyResources(generatedComponentsDir, stagedDir, stagedByName, componentName, generated: true);
        return stagedDir;
    }

    /// <summary>The top-level <c>metadata.name</c> of a single-document Dapr resource YAML.</summary>
    internal static string? MetadataName(string yaml) => Parse(yaml, "resource")?.Identity.Name;

    private static void CopyResources(
        string sourceDirectory,
        string stagedDirectory,
        Dictionary<string, StagedResource> stagedByName,
        string componentName,
        bool generated)
    {
        foreach (var file in ComponentFiles(sourceDirectory))
        {
            var yaml = File.ReadAllText(file);
            var resource = Parse(yaml, file) ?? throw new InvalidOperationException($"Dapr resource '{file}' has no metadata.name.");
            if (generated && resource.IsHttpEndpoint && !resource.Scopes.Contains(componentName, StringComparer.Ordinal))
            {
                continue;
            }

            if (stagedByName.TryGetValue(resource.Identity.Name, out var existing))
            {
                if (existing.IsGenerated == generated
                    || existing.Identity.ApiVersion != resource.Identity.ApiVersion
                    || existing.Identity.Kind != resource.Identity.Kind
                    || existing.Identity.Name != resource.Identity.Name)
                {
                    throw new InvalidOperationException(
                        $"Dapr resource '{file}' conflicts with an existing resource named '{resource.Identity.Name}'; replacement requires a unique matching apiVersion, kind, and metadata.name.");
                }

                var prior = Path.Combine(stagedDirectory, existing.Identity.FileName);
                File.Delete(prior);
            }

            var targetName = Path.GetFileName(file);
            var target = Path.Combine(stagedDirectory, targetName);
            File.Copy(file, target, overwrite: true);
            stagedByName[resource.Identity.Name] = new StagedResource(resource.Identity with { FileName = targetName }, generated);
        }
    }

    private static Resource? Parse(string yaml, string source)
    {
        if (yaml.Split("---", StringSplitOptions.None).Length > 1)
        {
            throw new InvalidOperationException($"Dapr resource '{source}' contains multiple YAML documents.");
        }

        string? apiVersion = null;
        string? kind = null;
        string? name = null;
        var scopes = new List<string>();
        var inMetadata = false;
        var inScopes = false;
        foreach (var raw in yaml.Split('\n'))
        {
            var line = raw.TrimEnd();
            if (line.StartsWith("apiVersion:", StringComparison.Ordinal)) apiVersion = Value(line);
            if (line.StartsWith("kind:", StringComparison.Ordinal)) kind = Value(line);
            if (line == "metadata:") { inMetadata = true; inScopes = false; continue; }
            if (line == "scopes:") { inScopes = true; inMetadata = false; continue; }
            if (inMetadata && raw.StartsWith(' ') && line.TrimStart().StartsWith("name:", StringComparison.Ordinal)) name = Value(line.TrimStart());
            if (inScopes && line.TrimStart().StartsWith("- ", StringComparison.Ordinal)) scopes.Add(Value(line.TrimStart()[2..]));
            if (!raw.StartsWith(' ') && !line.TrimStart().StartsWith("- ", StringComparison.Ordinal)
                && line.Length > 0 && line is not "metadata:" and not "scopes:") { inMetadata = false; inScopes = false; }
        }

        return name is null || apiVersion is null || kind is null
            ? null
            : new Resource(new ResourceIdentity(apiVersion, kind, name, Path.GetFileName(source)), scopes);
    }

    private static string Value(string line) => line[(line.IndexOf(':', StringComparison.Ordinal) + 1)..].Trim().Trim('"', '\'');

    private static IEnumerable<string> ComponentFiles(string directory) =>
        Directory.Exists(directory)
            ? Directory.EnumerateFiles(directory)
                .Where(file => file.EndsWith(".yaml", StringComparison.OrdinalIgnoreCase) || file.EndsWith(".yml", StringComparison.OrdinalIgnoreCase))
                .OrderBy(file => file, StringComparer.Ordinal)
            : [];

    private sealed record StagedResource(ResourceIdentity Identity, bool IsGenerated);

    private sealed record Resource(ResourceIdentity Identity, IReadOnlyList<string> Scopes)
    {
        public bool IsHttpEndpoint => Identity.Kind == "HTTPEndpoint";
    }

    private sealed record ResourceIdentity(string ApiVersion, string Kind, string Name, string FileName);
}

using System.Net.Sockets;
using Microsoft.Extensions.Diagnostics.HealthChecks;

namespace Intropy.Topology.Aspire;

internal interface IBackendReadiness
{
    Task WaitUntilReadyAsync(TimeSpan timeout, CancellationToken cancellationToken);
}

/// <summary>
/// Readiness probe for a published container port. A bare TCP connect is not enough: both the
/// Docker Desktop port proxy and Aspire's DCP endpoint proxy accept connections before the
/// backend listens — DCP holds them open in silence, so even "connection survives a read
/// window" passes against a proxy whose backend is down. When the probed protocol lets the
/// client speak first, pass its opening bytes as <paramref name="handshake"/>: readiness then
/// requires an actual response, which only the real backend can produce. Without a handshake,
/// silence within the read window still counts as ready (a listener with no banner).
/// </summary>
internal sealed class TcpReadyHealthCheck(string host, int port, ReadOnlyMemory<byte> handshake = default)
    : IHealthCheck, IBackendReadiness
{
    private static readonly TimeSpan s_readWindow = TimeSpan.FromMilliseconds(750);

    /// <summary>The inline RESP command "PING\r\n"; a ready Redis answers it with +PONG.</summary>
    public static ReadOnlyMemory<byte> RedisHandshake { get; } = "PING\r\n"u8.ToArray();

    /// <summary>Polls until the port is ready, throwing if it never becomes so.</summary>
    public async Task WaitUntilReadyAsync(TimeSpan timeout, CancellationToken cancellationToken)
    {
        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
        deadline.CancelAfter(timeout);
        try
        {
            while (true)
            {
                var result = await CheckHealthAsync(new HealthCheckContext(), deadline.Token).ConfigureAwait(false);
                if (result.Status == HealthStatus.Healthy)
                {
                    return;
                }

                await Task.Delay(TimeSpan.FromSeconds(1), deadline.Token).ConfigureAwait(false);
            }
        }
        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
        {
            throw new InvalidOperationException($"{host}:{port} did not become ready within {timeout}.");
        }
    }

    public async Task<HealthCheckResult> CheckHealthAsync(
        HealthCheckContext context, CancellationToken cancellationToken = default)
    {
        try
        {
            using var client = new TcpClient();
            await client.ConnectAsync(host, port, cancellationToken).ConfigureAwait(false);
            var stream = client.GetStream();
            if (!handshake.IsEmpty)
            {
                await stream.WriteAsync(handshake, cancellationToken).ConfigureAwait(false);
            }

            using var readWindow = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
            readWindow.CancelAfter(s_readWindow);
            try
            {
                var read = await stream.ReadAsync(new byte[1], readWindow.Token).ConfigureAwait(false);
                return read > 0
                    ? HealthCheckResult.Healthy()
                    : HealthCheckResult.Unhealthy($"{host}:{port} closed the connection immediately.");
            }
            catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
            {
                // No bytes within the window but the connection stayed open. A real listener may
                // simply have no banner; a proxy dialing a dead backend looks exactly the same,
                // so with a handshake in flight only an actual response counts.
                return handshake.IsEmpty
                    ? HealthCheckResult.Healthy()
                    : HealthCheckResult.Unhealthy($"{host}:{port} did not answer the handshake.");
            }
        }
        catch (SocketException ex)
        {
            return HealthCheckResult.Unhealthy($"{host}:{port} not reachable: {ex.Message}");
        }
        catch (IOException ex)
        {
            return HealthCheckResult.Unhealthy($"{host}:{port} dropped the connection: {ex.Message}");
        }
    }
}

namespace Intropy.Topology.Aspire;

/// <summary>
/// Locates a component's integration by folder convention: a component named
/// <c>order-extractor</c> lives in the sibling folder <c>../order-extractor/</c>, relative to
/// the AppHost. The project is <c>src/*.csproj</c> inside it (the scaffold layout), falling
/// back to a flat <c>order-extractor.csproj</c>; its local Dapr components live in
/// <c>local/dapr-components/</c>.
/// </summary>
internal static class ProjectConvention
{
    /// <summary>The integration's root folder: the sibling folder named after the component.</summary>
    public static string IntegrationRoot(string appHostDirectory, string componentName) =>
        Path.GetFullPath(Path.Combine(appHostDirectory, "..", componentName));

    /// <summary>The project that runs the component: <c>src/*.csproj</c>, else <c>{name}.csproj</c> flat.</summary>
    public static string Resolve(string appHostDirectory, string componentName)
    {
        var root = IntegrationRoot(appHostDirectory, componentName);
        var srcDirectory = Path.Combine(root, "src");
        if (Directory.Exists(srcDirectory) &&
            Directory.GetFiles(srcDirectory, "*.csproj") is [var project])
        {
            return project;
        }

        return Path.Combine(root, componentName + ".csproj");
    }

    /// <summary>The integration's own Dapr components — the set it runs on standalone.</summary>
    public static string LocalComponentsDir(string appHostDirectory, string componentName) =>
        Path.Combine(IntegrationRoot(appHostDirectory, componentName), "local", "dapr-components");
}

using System.Globalization;
using System.Text;

namespace Intropy.Topology;

/// <summary>
/// Thrown by <see cref="SystemBuilder.Build"/> when the declared topology has one or
/// more error-severity violations. Carries every diagnostic found — not just the first —
/// so a SystemHost run reports the whole picture at once.
/// </summary>
public sealed class TopologyValidationException : Exception
{
    /// <summary>All diagnostics found, including warnings.</summary>
    public IReadOnlyList<TopologyDiagnostic> Diagnostics { get; }

    /// <summary>Creates the exception with no diagnostics.</summary>
    public TopologyValidationException()
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception with a message and no diagnostics.</summary>
    /// <param name="message">The exception message.</param>
    public TopologyValidationException(string message)
        : base(message)
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception with a message, an inner exception, and no diagnostics.</summary>
    /// <param name="message">The exception message.</param>
    /// <param name="innerException">The causing exception.</param>
    public TopologyValidationException(string message, Exception innerException)
        : base(message, innerException)
    {
        Diagnostics = [];
    }

    /// <summary>Creates the exception from the full diagnostic list.</summary>
    /// <param name="diagnostics">All diagnostics found while validating the topology.</param>
    public TopologyValidationException(IReadOnlyList<TopologyDiagnostic> diagnostics)
        : base(BuildMessage(diagnostics))
    {
        Diagnostics = diagnostics;
    }

    private static string BuildMessage(IReadOnlyList<TopologyDiagnostic> diagnostics)
    {
        var errorCount = diagnostics.Count(d => d.Severity == DiagnosticSeverity.Error);
        var builder = new StringBuilder();
        builder.Append(CultureInfo.InvariantCulture, $"The system topology is invalid ({errorCount} error(s)):");
        foreach (var diagnostic in diagnostics)
        {
            builder.AppendLine();
            builder.Append(CultureInfo.InvariantCulture, $"  [{diagnostic.Severity}]");
            if (diagnostic.Target is not null)
            {
                builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Target}:");
            }

            builder.Append(CultureInfo.InvariantCulture, $" {diagnostic.Message}");
        }

        return builder.ToString();
    }
}

